<script>
document.addEventListener('DOMContentLoaded',()=>{
 const editImageInput=document.getElementById('editAnnouncementImage');if(editImageInput){editImageInput.addEventListener('change',()=>{const preview=document.getElementById('editPreview'),file=editImageInput.files?.[0];if(file&&preview){preview.src=URL.createObjectURL(file);preview.style.display='block';}});}
 const imageInput=document.getElementById('announcementImage'), imagePreview=document.getElementById('announcementImagePreview');
 if(imageInput&&imagePreview){imageInput.addEventListener('change',()=>{const file=imageInput.files&&imageInput.files[0];if(imagePreview.dataset.objectUrl){URL.revokeObjectURL(imagePreview.dataset.objectUrl);delete imagePreview.dataset.objectUrl;}if(file&&file.type.startsWith('image/')){const url=URL.createObjectURL(file);imagePreview.src=url;imagePreview.dataset.objectUrl=url;imagePreview.style.display='block';}else{imagePreview.removeAttribute('src');imagePreview.style.display='none';}});}

 if(window.lucide)window.lucide.createIcons();
 const body=document.body,toggle=document.getElementById('sidebarToggle'),shade=document.getElementById('shade');
 const mobile=()=>window.matchMedia('(max-width:820px)').matches;
 const closeMobile=()=>{body.classList.remove('mobile-open');toggle.setAttribute('aria-expanded','false')};
 try{if(!mobile()&&localStorage.getItem('brew_superadmin_sidebar_collapsed')==='1')body.classList.add('sidebar-collapsed')}catch(e){}
 toggle.setAttribute('aria-expanded',String(!body.classList.contains('sidebar-collapsed')));
 toggle.addEventListener('click',()=>{if(mobile()){const open=body.classList.toggle('mobile-open');toggle.setAttribute('aria-expanded',String(open))}else{const collapsed=body.classList.toggle('sidebar-collapsed');toggle.setAttribute('aria-expanded',String(!collapsed));try{localStorage.setItem('brew_superadmin_sidebar_collapsed',collapsed?'1':'0')}catch(e){}}});
 shade.addEventListener('click',closeMobile);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobile()});window.addEventListener('resize',()=>{if(!mobile())body.classList.remove('mobile-open')});
 const panel=document.getElementById('createPanel'),open=document.getElementById('openCreate'),close=document.getElementById('closeCreate');
 open?.addEventListener('click',()=>{panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'start'});panel.querySelector('input[name="title"]')?.focus({preventScroll:true})});close?.addEventListener('click',()=>{panel.hidden=true});
 const search=document.getElementById('announcementSearch'),status=document.getElementById('statusFilter'),rows=[...document.querySelectorAll('#announcementRows tr[data-search]')],empty=document.getElementById('noMatches'),count=document.getElementById('visibleCount');
 const apply=()=>{let shown=0;const term=search.value.trim().toLowerCase();rows.forEach(row=>{const match=row.dataset.search.includes(term)&&(status.value==='all'||row.dataset.status===status.value);row.classList.toggle('hidden-row',!match);if(match)shown++});empty.hidden=shown>0||rows.length===0;count.textContent=String(shown)};
 search?.addEventListener('input',apply);status?.addEventListener('change',apply);
});
</script>
</body></html>
